// ==========================================
// 1. 取得 Trigger 傳入的所有檔案項目
// ==========================================
const items = $input.all();

// ==========================================
// 2. 關鍵安全性過濾（排除非 PDF 與暫存檔）
// ==========================================
const validItems = items.filter(item => {
    const fileName = item.json.name;

    // 如果沒有檔名，直接過濾掉
    if (!fileName) return false;

    const lowerName = fileName.toLowerCase();

    // 必須是 .pdf 結尾，且不能是 Google 生成時的暫時檔名 'export.pdf'
    return lowerName.endsWith('.pdf') && lowerName !== 'export.pdf';
});

// ==========================================
// 3. 處理檔名轉換與組裝輸出資料
// ==========================================
// 註：這裡不再用 slice() 限制批次筆數。
// Zeabur 轉檔服務已經用 semaphore 做同時併發數限制，
// n8n 這邊一次抓到幾筆就往下送幾筆，多餘的請求會在伺服器端自動排隊，
// 不會再有檔案因為被砍掉而永久遺失。
return validItems.map(item => {
    // 提取檔名與檔案 ID
    const fileName = item.json.name;
    const fileId = item.json.id;

    // 剔除原本的副檔名 (例如：report.pdf -> report)
    const cleanName = fileName.replace(/\.[^/.]+$/, "");

    // 組裝輸出的 JPG 檔名與 Telegram 通知訊息
    const outputJpgName = `${cleanName}.jpg`;
    const tgMessage = `📄 ${fileName} 已成功送出轉檔`;

    // 回傳精簡資料給後續節點（Download -> HTTP Request -> Upload -> Move）使用
    return {
        json: {
            originalId: String(fileId),
            originalName: String(fileName),
            jpgName: String(outputJpgName),
            tgText: String(tgMessage)
        }
    };
});

// 1. 跨節點直接抓取「Code in JavaScript1」這個節點輸出的所有項目資料
const sourceItems = $('Code in JavaScript1').all();

// 2. 提取出所有項目的 tgText 欄位，並用換行符號連接起來
const fileList = sourceItems.map((item, index) => {
    // 如果找不到 tgText，就顯示未知名稱
    const text = item.json.tgText || "未取得文字資訊";
    return `${index + 1}. ${text}`;
}).join('\n');

// 3. 計算總共有多少個檔案
const totalCount = sourceItems.length;

// 4. 組裝成最終要發送給 Telegram 的單一訊息
const finalMessage = `
${fileList}

統計：共成功轉換 ${totalCount} 個檔案。
`.trim();

// 5. 只回傳一個項目給 Telegram 與後續 Webhook 節點
return [
  {
    json: {
      combinedMessage: finalMessage,
      fileCount: totalCount
    }
  }
];

// ==========================================
// 1. 核心通用配置與函式
// ==========================================
const pageSize = 4; // 每頁最多顯示的公司數量
const TIME_TOLERANCE_MS = 120000; // 容許時間差：2 分鐘 (120,000 毫秒)

// 千分位格式化函式
const formatPrice = (val) => {
  if (val === undefined || val === null || val === "" || isNaN(parseFloat(val))) return "--";
  return parseFloat(val).toLocaleString('en-US');
};

// 解析修改狀態時間點
function parseModifyStatusToMs(statusStr) {
  const str = String(statusStr || "").trim();
  let match = str.match(/(\d{1,2})\/(\d{1,2})\s+(\d{1,2}):(\d{1,2})修改/);
  if (match) {
    const month = parseInt(match[1], 10) - 1;
    const day = parseInt(match[2], 10);
    const hour = parseInt(match[3], 10);
    const minute = parseInt(match[4], 10);
    const currentYear = new Date().getFullYear();
    return new Date(currentYear, month, day, hour, minute, 0, 0).getTime();
  }
  match = str.match(/修改(?:\d+_)?(\d{2})(\d{2})-(\d{2})(\d{2})/);
  if (!match) return 0;
  const month = parseInt(match[1], 10) - 1;
  const day = parseInt(match[2], 10);
  const hour = parseInt(match[3], 10);
  const minute = parseInt(match[4], 10);
  const currentYear = new Date().getFullYear();
  return new Date(currentYear, month, day, hour, minute, 0, 0).getTime();
}

// 生成單一用戶的 Flex Carousel
function generateFlexCarousel(clients, amounts, statuses, links, changeTimes, bankAccountRaw, displayName = "") {
  let bankAccount = bankAccountRaw || "暫無帳號資訊";
  bankAccount = bankAccount.replace(/(北中壢分行)[\s\u3000]*/g, "$1\n");

  let anyNotIssued = false;
  let anyModifying = false; // 紀錄是否有任何帳單修改中
  let calculatedTotalAmount = 0;
  let latestTimeMs = 0;
  const clientTimesMs = [];
  const downloadableClients = [];

  for (let j = 0; j < clients.length; j++) {
    const checkAmt = amounts[j];
    const checkLink = String(links[j] || "").trim();
    const rawStatus = String(statuses[j] || "").trim();
    const ct = String(changeTimes[j] ?? "0").trim();
    const isModifying = ct !== "0" && ct !== "";
    const isNotIssued = checkLink === "尚未出帳" || String(checkAmt).includes("#N/A");

    if (isNotIssued) anyNotIssued = true;
    if (isModifying) anyModifying = true;

    if (!isNotIssued && !isModifying) {
      downloadableClients.push(clients[j]);
      if (!isNaN(parseFloat(checkAmt))) {
        calculatedTotalAmount += parseFloat(checkAmt);
      }
    }

    const timeMs = parseModifyStatusToMs(rawStatus);
    clientTimesMs.push(timeMs);
    if (timeMs > latestTimeMs) latestTimeMs = timeMs;
  }

  const isLatestModified = [];
  for (let j = 0; j < clients.length; j++) {
    const rawStatus = String(statuses[j] || "").trim();
    const hasModifyMark = rawStatus.includes("修改");
    isLatestModified.push(clients.length > 1 && hasModifyMark);
  }

  const bubbles = [];

  let downloadButton = null;

  if (anyNotIssued) {
    downloadButton = {
      "type": "button",
      "action": {
        "type": "postback",
        "label": "尚未出帳，無法下載",
        "data": "action=bill_not_ready"
      },
      "style": "primary",
      "color": "#888888"
    };
  } else if (anyModifying) {
    downloadButton = {
      "type": "button",
      "action": {
        "type": "postback",
        "label": "⚠️ 帳單修改中 (暫不可下載)",
        "data": "action=bill_not_ready"
      },
      "style": "primary",
      "color": "#888888"
    };
  } else {
    const downloadClientNames = downloadableClients.join(',');
    const allPostbackData = `action=download_bill&clients=${downloadClientNames}`;
    downloadButton = {
      "type": "button",
      "action": {
        "type": "postback",
        "label": "下載全部帳單",
        "data": allPostbackData,
        "displayText": "正在下載帳單，請稍候..."
      },
      "style": "primary",
      "color": "#1DB446"
    };
  }

  const coverBubble = {
    "type": "bubble",
    "size": "mega",
    "header": {
      "type": "box",
      "layout": "vertical",
      "paddingBottom": "none",
      "contents": [
        { "type": "text", "text": "🔔 帳單通知", "weight": "bold", "size": "lg", "color": "#111111" }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "paddingTop": "md",
      "spacing": "md",
      "contents": [
        { 
          "type": "text", 
          "text": "請盡速核對帳單，如有錯誤請儘速告知修正：", 
          "wrap": true, 
          "size": "md", 
          "color": "#111111" 
        },
        { "type": "separator", "margin": "md" },

        // ❶ 下載帳單
        {
          "type": "box",
          "layout": "horizontal",
          "spacing": "md",
          "margin": "md",
          "contents": [
            {
              "type": "text",
              "text": "❶",
              "size": "xl",
              "color": "#1DB446",
              "weight": "bold",
              "flex": 0,
              "gravity": "center"
            },
            {
              "type": "box",
              "layout": "vertical",
              "flex": 1,
              "contents": [
                { "type": "text", "text": "下載帳單", "weight": "bold", "size": "lg", "color": "#111111" },
                { "type": "text", "text": "點下方按鈕下載帳單明細", "size": "md", "color": "#666666", "margin": "xs" }
              ]
            }
          ]
        },

        // ❷ 費用總覽
        {
          "type": "box",
          "layout": "horizontal",
          "spacing": "md",
          "margin": "md",
          "contents": [
            {
              "type": "text",
              "text": "❷",
              "size": "xl",
              "color": "#1DB446",
              "weight": "bold",
              "flex": 0,
              "gravity": "center"
            },
            {
              "type": "box",
              "layout": "vertical",
              "flex": 1,
              "contents": [
                { "type": "text", "text": "費用總覽", "weight": "bold", "size": "lg", "color": "#111111" },
                { "type": "text", "text": "右滑查看各公司應繳金額", "size": "md", "color": "#666666", "margin": "xs" }
              ]
            }
          ]
        },

        // ❸ 匯款對帳
        {
          "type": "box",
          "layout": "horizontal",
          "spacing": "md",
          "margin": "md",
          "contents": [
            {
              "type": "text",
              "text": "❸",
              "size": "xl",
              "color": "#1DB446",
              "weight": "bold",
              "flex": 0,
              "gravity": "center"
            },
            {
              "type": "box",
              "layout": "vertical",
              "flex": 1,
              "contents": [
                { "type": "text", "text": "匯款對帳", "weight": "bold", "size": "lg", "color": "#111111" },
                { "type": "text", "text": "完成後煩請提供資訊對帳", "size": "md", "color": "#666666", "margin": "xs" }
              ]
            }
          ]
        }
      ]
    }
  };

  if (downloadButton) {
    coverBubble.footer = {
      "type": "box",
      "layout": "vertical",
      "contents": [downloadButton]
    };
  }

  bubbles.push(coverBubble);

  const isMultiPage = clients.length > pageSize;
  for (let i = 0; i < clients.length; i += pageSize) {
    const currentBatch = clients.slice(i, i + pageSize);
    const isLastBubble = (i + pageSize) >= clients.length;
    const rows = [];
    let pageSubtotal = 0;

    currentBatch.forEach((name, index) => {
      const realIndex = i + index;
      const isLastItemInBatch = index === currentBatch.length - 1;
      let valAmount = amounts[realIndex];
      let displayAmount = formatPrice(valAmount);
      const rawStatus = String(statuses[realIndex] || "").trim();
      const rawLink = String(links[realIndex] || "").trim();
      const ct = String(changeTimes[realIndex] ?? "0").trim();

      const isNotIssued = rawLink === "尚未出帳" || String(valAmount).includes("#N/A");
      const isModifying = ct !== "0" && ct !== "";

      if (!isNotIssued && !isModifying && !isNaN(parseFloat(valAmount))) {
        pageSubtotal += parseFloat(valAmount);
      }

      const timeMs = clientTimesMs[realIndex];
      const isTheNewestOne = latestTimeMs > 0 && timeMs > 0 && (latestTimeMs - timeMs) <= TIME_TOLERANCE_MS;

      let displayNameWithMark = name || "未知公司";
      if (clients.length > 1 && isTheNewestOne) {
        displayNameWithMark = `✨ ${displayNameWithMark}`;
      }

      let contentBox = [];
      if (isNotIssued) {
        contentBox = [
          { "type": "text", "text": displayNameWithMark, "weight": "bold", "size": "lg", "color": "#111111", "wrap": true },
          { "type": "text", "text": "該用戶尚未出帳", "size": "sm", "color": "#999999", "margin": "xs", "style": "italic" }
        ];
      } else if (isModifying) {
        contentBox = [
          { "type": "text", "text": displayNameWithMark, "weight": "bold", "size": "lg", "color": "#E67E22", "wrap": true },
          {
            "type": "box",
            "layout": "horizontal",
            "margin": "xs",
            "contents": [
              {
                "type": "text",
                "text": "⏳ 帳單修改中，請稍候",
                "size": "sm",
                "color": "#E67E22",
                "weight": "bold",
                "style": "italic"
              }
            ]
          }
        ];
      } else {
        const targetColor = isTheNewestOne ? "#E67E22" : "#111111";
        const textInfoContents = [
          {
            "type": "text",
            "text": `金額：${displayAmount}`,
            "size": "sm",
            "color": targetColor,
            "weight": "bold"
          }
        ];

        if (rawStatus !== "") {
          textInfoContents.push({
            "type": "text",
            "text": rawStatus,
            "size": "sm",
            "color": targetColor,
            "weight": "bold",
            "margin": "xs"
          });
        }

        const detailsRowContents = [
          {
            "type": "box",
            "layout": "vertical",
            "flex": 1,
            "contents": textInfoContents
          }
        ];

        if (isLatestModified[realIndex]) {
          const displayStatus = rawStatus !== "" ? rawStatus : "修改";
          detailsRowContents.push({
            "type": "button",
            "action": {
              "type": "postback",
              "label": "下載",
              "data": `action=download_bill&clients=${name}`,
              "displayText": `正在下載 ${name} ${displayStatus} 的帳單`
            },
            "style": "primary",
            "color": "#E67E22",
            "height": "sm",
            "flex": 0,
            "gravity": "center"
          });
        }

        contentBox = [
          { "type": "text", "text": displayNameWithMark, "weight": "bold", "size": "lg", "color": isTheNewestOne ? "#E67E22" : "#111111", "wrap": true },
          { "type": "box", "layout": "horizontal", "margin": "xs", "contents": detailsRowContents }
        ];
      }

      if (!isLastItemInBatch) contentBox.push({ "type": "separator", "margin": "md" });

      const clientBox = { "type": "box", "layout": "vertical", "spacing": "xs", "contents": contentBox };
      if (index > 0) {
        clientBox.margin = "lg";
      }
      rows.push(clientBox);
    });

    if (isMultiPage) {
      rows.push({ "type": "separator", "margin": "xl", "color": "#eeeeee" });
      rows.push({ "type": "box", "layout": "horizontal", "margin": "md", "contents": [{ "type": "text", "text": "本頁小計", "size": "sm", "color": "#888888", "gravity": "center" }, { "type": "text", "text": `NT$ ${formatPrice(pageSubtotal)}`, "size": "md", "weight": "bold", "color": "#111111", "align": "end" }] });
    }

    if (isLastBubble) {
      rows.push({ "type": "separator", "margin": "xl", "color": "#eeeeee" });
      rows.push(
        { "type": "text", "text": "合計總金額", "size": "sm", "color": "#888888", "align": "end", "margin": "md" },
        { "type": "text", "text": `NT$ ${formatPrice(calculatedTotalAmount)}`, "size": "xxl", "weight": "bold", "color": "#E63946", "align": "end", "adjustMode": "shrink-to-fit" }
      );
    }

    const pageIndex = (i / pageSize) + 1;
    const headerTitle = isMultiPage ? `📋 帳單總覽 (${pageIndex})` : "📋 帳單總覽";

    const bubble = { 
      "type": "bubble", 
      "size": "mega", 
      "header": { 
        "type": "box", 
        "layout": "vertical", 
        "paddingBottom": "none",
        "contents": [{ "type": "text", "text": headerTitle, "weight": "bold", "size": "lg", "color": "#111111" }] 
      }, 
      "body": { 
        "type": "box", 
        "layout": "vertical", 
        "paddingTop": "md",
        "contents": rows 
      } 
    };

    if (isLastBubble) {
      bubble.footer = {
        "type": "box",
        "layout": "vertical",
        "contents": [
          {
            "type": "box",
            "layout": "vertical",
            "backgroundColor": "#F7F7F7",
            "paddingAll": "md",
            "cornerRadius": "sm",
            "action": {
              "type": "clipboard",
              "clipboardText": bankAccountRaw || bankAccount
            },
            "contents": [
              {
                "type": "box",
                "layout": "horizontal",
                "contents": [
                  { "type": "text", "text": "🏦 匯款帳號", "size": "sm", "color": "#888888", "weight": "bold" },
                  { "type": "text", "text": "📋 點擊複製", "size": "xs", "color": "#1DB446", "align": "end", "weight": "bold" }
                ]
              },
              { "type": "text", "text": bankAccount, "size": "lg", "color": "#111111", "weight": "bold", "wrap": true, "margin": "xs" }
            ]
          }
        ]
      };
    }

    bubbles.push(bubble);
  }

  return {
    flexJsonString: JSON.stringify({ "type": "carousel", "contents": bubbles }),
    anyNotIssued: anyNotIssued
  };
}

// ==========================================
// 2. 模式自動偵測與資料解析
// ==========================================
const firstInput = $input.first()?.json || {};

if (Array.isArray(firstInput["客戶名稱"])) {
  const clients = firstInput["客戶名稱"] || [];
  const amounts = firstInput["帳單金額"] || [];
  const statuses = firstInput["狀態"] || [];
  const links = firstInput["JPG連結"] || [];
  const changeTimes = firstInput["變更時間"] || [];
  const bankAccountRaw = Array.isArray(firstInput["匯款帳號"]) ? firstInput["匯款帳號"][0] : firstInput["匯款帳號"];

  const result = generateFlexCarousel(clients, amounts, statuses, links, changeTimes, bankAccountRaw);

  return [{
    json: {
      flexJsonString: result.flexJsonString,
      clientNames: clients,
      anyNotIssued: result.anyNotIssued,
      mode: "A"
    }
  }];

} else {
  const paidContacts = $('取得可傳帳單名單').all()
    .map(item => item.json)
    .filter(contact => {
      const uId = contact["B:userId"] || contact["userId"];
      return uId && String(uId).trim() !== "";
    });

  const allBills = $('取得所有帳單明細').all()
    .map(item => item.json)
    .filter(b => {
      if (!b) return false;
      const hasCode = b["編號"] && String(b["編號"]).trim() !== "";
      const hasClientName = b["客戶名稱"] && String(b["客戶名稱"]).trim() !== "";
      return hasCode && hasClientName;
    });

  const billMap = {};
  allBills.forEach(b => {
    if (b["編號"]) billMap[String(b["編號"]).trim()] = b;
  });

  const lineTasks = [];
  const personToCompanies = {};
  const updateCodesSet = new Set();
  const groupedContacts = {};

  paidContacts.forEach(contact => {
    const userId = contact["B:userId"] || contact["userId"];
    if (!userId) return;

    if (!groupedContacts[userId]) {
      groupedContacts[userId] = {
        userId: userId,
        displayName: contact["C:displayName"] || contact["displayName"],
        allCodes: new Set()
      };
    }

    for (let i = 1; i <= 10; i++) {
      const codeVal = contact[`編號${i}`];
      if (codeVal && String(codeVal).trim() !== "") {
        groupedContacts[userId].allCodes.add(String(codeVal).trim());
      }
    }
  });

  Object.values(groupedContacts).forEach(userGroup => {
    const userId = userGroup.userId;
    const displayName = userGroup.displayName;
    const matchedBills = [];

    userGroup.allCodes.forEach(cleanCode => {
      const matchedBill = billMap[cleanCode];
      if (matchedBill) {
        matchedBills.push(matchedBill);
        updateCodesSet.add(cleanCode);
        if (displayName && matchedBill["客戶名稱"]) {
          if (!personToCompanies[displayName]) personToCompanies[displayName] = new Set();
          personToCompanies[displayName].add(matchedBill["客戶名稱"].trim());
        }
      }
    });

    if (matchedBills.length === 0) return;

    const clients = matchedBills.map(b => b["客戶名稱"]);
    const amounts = matchedBills.map(b => b["帳單金額"]);
    const statuses = matchedBills.map(b => b["狀態"]);
    const links = matchedBills.map(b => b["JPG連結"]);
    const changeTimes = matchedBills.map(b => b["變更時間"]);
    const bankAccountRaw = matchedBills[0]["匯款帳號"];

    const result = generateFlexCarousel(clients, amounts, statuses, links, changeTimes, bankAccountRaw, displayName);

    lineTasks.push({
      userId: userId,
      flexJsonString: result.flexJsonString
    });
  });

  const tgKeys = Object.keys(personToCompanies).filter(k => personToCompanies[k].size > 0);
  let tgText = "<b>📊 已發送帳單摘要</b>\n";
  let tgKeysCount = tgKeys.length;
  tgText += `<code>共計發送至 ${tgKeysCount} 個帳號</code>\n\n`;
  tgKeys.forEach(name => {
    tgText += `<b>🟢 ${name}</b>\n`;
    Array.from(personToCompanies[name]).forEach(company => {
      tgText += ` • ${company}\n`;
    });
    tgText += "\n";
  });

  const updateList = Array.from(updateCodesSet).map(code => ({ json: { "編號": code } }));

  return [{
    json: {
      lineTasks: lineTasks,
      tgText: tgText,
      updateList: updateList,
      mode: "B"
    }
  }];
}

// ==========================================
// 已繳費名單與帳單明細彙整處理 (三路分流前置 - Carousel 滑動版)
// ==========================================

// 千分位格式化函式
const formatPrice = (val) => {
  if (val === undefined || val === null || val === "" || isNaN(parseFloat(val))) return "0";
  return parseFloat(val).toLocaleString('en-US');
};

// 1. 取得「已繳費名單」
const paidContacts = $('取得已繳費名單1').all()
  .map(item => item.json)
  .filter(contact => {
    const uId = contact["B:userId"] || contact["userId"];
    return uId && String(uId).trim() !== "";
  });

// 2. 取得「所有帳單明細」
const allBills = $('取得所有帳單明細2').all()
  .map(item => item.json)
  .filter(b => {
    if (!b) return false;
    const hasCode = b["編號"] && String(b["編號"]).trim() !== "";
    const hasClientName = b["客戶名稱"] && String(b["客戶名稱"]).trim() !== "";
    return hasCode && hasClientName;
  });

// 建立帳單快速搜尋 Map
const billMap = {};
allBills.forEach(b => {
  if (b["編號"]) billMap[String(b["編號"]).trim()] = b;
});

const lineTasks = [];
const updateCodesSet = new Set();
const personToCompanies = {};
const groupedContacts = {};

// 3. 處理已付款聯絡人與其對應的帳單
paidContacts.forEach(contact => {
  const userId = contact["B:userId"] || contact["userId"];
  const displayName = contact["C:displayName"] || contact["displayName"] || "客戶";
  if (!userId) return;

  if (!groupedContacts[userId]) {
    groupedContacts[userId] = {
      userId: userId,
      displayName: displayName,
      allCodes: new Set()
    };
  }

  for (let i = 1; i <= 10; i++) {
    const codeVal = contact[`編號${i}`] || contact[`USERID-${i}`];
    if (codeVal && String(codeVal).trim() !== "") {
      groupedContacts[userId].allCodes.add(String(codeVal).trim());
    }
  }

  if (contact["編號"] && String(contact["編號"]).trim() !== "") {
    groupedContacts[userId].allCodes.add(String(contact["編號"]).trim());
  }
});

// 4. 比對出真正需要更新與發送通知的資料 (每 5 家公司切分為一張卡片，組成 Carousel)
Object.values(groupedContacts).forEach(userGroup => {
  const userId = userGroup.userId;
  const displayName = userGroup.displayName;
  const matchedBills = [];

  userGroup.allCodes.forEach(cleanCode => {
    const matchedBill = billMap[cleanCode];
    if (matchedBill) {
      matchedBills.push(matchedBill);
      updateCodesSet.add(cleanCode);

      if (!personToCompanies[displayName]) {
        personToCompanies[displayName] = new Set();
      }
      personToCompanies[displayName].add(matchedBill["客戶名稱"].trim());
    }
  });

  if (matchedBills.length === 0) return;

  // 計算全部帳單總金額
  const grandTotalAmount = matchedBills.reduce((sum, b) => sum + (parseFloat(b["已入金額"]) || 0), 0);

  // 設定每張卡片最多放 5 家客戶
  const CHUNK_SIZE = 5;
  const totalPages = Math.ceil(matchedBills.length / CHUNK_SIZE);
  const bubbles = [];

  for (let i = 0; i < matchedBills.length; i += CHUNK_SIZE) {
    const chunk = matchedBills.slice(i, i + CHUNK_SIZE);
    const currentPage = Math.floor(i / CHUNK_SIZE) + 1;

    // 標題設定 (配合圖片風格加上 Icon 與深藍色)
    const headerTitle = totalPages > 1 
      ? `款項入帳完成通知 (${currentPage}/${totalPages})` 
      : `款項入帳完成通知`;

    const bodyContents = [
      {
        "type": "box",
        "layout": "horizontal",
        "margin": "none",
        "contents": [
          {
            "type": "text",
            "text": "✅",
            "size": "md",
            "flex": 0,
            "margin": "none"
          },
          {
            "type": "text",
            "text": headerTitle,
            "weight": "bold",
            "size": "md",
            "color": "#1E3A8A",
            "margin": "sm",
            "flex": 1,
            "adjustMode": "shrink-to-fit"
          }
        ]
      },
      {
        "type": "separator",
        "margin": "md",
        "color": "#E2E8F0"
      }
    ];

    let chunkTotalAmount = 0;

    chunk.forEach((bill, idx) => {
      const companyName = String(bill["客戶名稱"] || "").trim();
      const amtVal = parseFloat(bill["已入金額"]) || 0;
      chunkTotalAmount += amtVal;

      // 左右 7:3 排版，顏色與字體比照帳單總覽
      bodyContents.push({
        "type": "box",
        "layout": "horizontal",
        "margin": (idx === 0) ? "lg" : "md",
        "paddingStart": "md",
        "paddingEnd": "md",
        "contents": [
          {
            "type": "text",
            "text": companyName,
            "weight": "bold",
            "size": "sm",
            "color": "#0F172A",          // 深色字體
            "flex": 7,                   // 左側 7 份寬度
            "wrap": true,                // 允許換行
            "maxLines": 2,               // 最多跨到第二排
            "adjustMode": "shrink-to-fit"
          },
          {
            "type": "text",
            "text": `${formatPrice(amtVal)}`, // 只有金額數字
            "weight": "bold",
            "size": "sm",
            "color": "#1E3A8A",          // 藍色字體 (比照圖片中的金額樣式)
            "flex": 3,                   // 右側 3 份寬度
            "align": "end",              // 靠右對齊
            "gravity": "center"          // 若公司名稱換行，金額垂直置中
          }
        ]
      });
    });

    // 合計區塊 (模仿圖片右側的總計樣式：淺灰底、紅色大字)
    if (totalPages > 1 || chunk.length > 1) {
      const totalBoxContents = [];

      if (currentPage === totalPages) {
        totalBoxContents.push({
          "type": "text",
          "text": "合計總金額",
          "size": "xs",
          "color": "#64748B",
          "align": "end"
        });
        totalBoxContents.push({
          "type": "text",
          "text": `NT$ ${formatPrice(grandTotalAmount)}`,
          "size": "xl",
          "color": "#EF4444",
          "weight": "bold",
          "align": "end",
          "margin": "xs"
        });
      } else {
        totalBoxContents.push({
          "type": "text",
          "text": "本頁小計",
          "size": "xs",
          "color": "#64748B",
          "align": "end"
        });
        totalBoxContents.push({
          "type": "text",
          "text": `NT$ ${formatPrice(chunkTotalAmount)}`,
          "size": "xl",
          "color": "#1E3A8A",
          "weight": "bold",
          "align": "end",
          "margin": "xs"
        });
      }

      bodyContents.push({
        "type": "box",
        "layout": "vertical",
        "margin": "xl",
        "paddingAll": "md",
        "backgroundColor": "#F8FAFC",
        "cornerRadius": "md",
        "contents": totalBoxContents
      });
    }

    bubbles.push({
      "type": "bubble",
      "size": "kilo",
      "body": {
        "type": "box",
        "layout": "vertical",
        "contents": bodyContents
      },
      "footer": {
        "type": "box",
        "layout": "vertical",
        "contents": [
          {
            "type": "text",
            "text": "感謝您的支持與配合",
            "size": "sm",
            "color": "#64748B",
            "align": "center",
            "wrap": true
          }
        ]
      }
    });
  }

  // 判斷：單頁傳 Bubble；多頁包裝為 Carousel
  const flexPayload = totalPages > 1
    ? { "type": "carousel", "contents": bubbles }
    : bubbles[0];

  lineTasks.push({
    userId: userId,
    flexJsonString: JSON.stringify(flexPayload)
  });
});

// 5. 彙整 Telegram 報告
const tgKeys = Object.keys(personToCompanies).filter(k => personToCompanies[k].size > 0);
let tgText = "<b>💵 已確認收款摘要</b>\n";
tgText += `<code>共計發送 ${tgKeys.length} 個帳號</code>\n\n`;

tgKeys.forEach(name => {
  tgText += `<b>🟢 ${name} </b>\n`;
  Array.from(personToCompanies[name]).forEach(company => {
    tgText += ` • ${company}\n`;
  });
  tgText += "\n";
});

// 6. 彙整待回寫 401 表的「已繳」更新清單
const updateList = Array.from(updateCodesSet).map(code => ({
  "編號": code,
  "狀態": "已繳款"
}));

if (updateList.length === 0) return [];

return [{
  json: {
    lineTasks: lineTasks,
    tgText: tgText,
    updateList: updateList
  }
}];

