parameters.jsCode:
// ==========================================================
// 🎯 防呆相容版 Compare & Match Data
// ==========================================================

let allFiles = [];
try {
  allFiles = $('List Drive Files').all();
} catch (e) {
  allFiles = $input.all().filter(item => item.json && item.json.id && item.json.name);
}

let customerMap = [];
try {
  customerMap = $('Filter').all();
} catch (e) {
  customerMap = [];
}

let folderList = [];
try {
  folderList = $('Get Folders Sheet').all();
} catch (e) {
  folderList = [];
}

// 建立資料夾清單與 F 欄檔名白名單字典
const folderMap = {};
for (const folder of folderList) {
  const fId = folder.json['資料夾ID'];
  const fName = folder.json['資料夾名稱'];

  const sentFilesString = folder.json['已發送檔案清單'] || folder.json['已發送檔案'] || folder.json['今日檔案列表'] ? String(folder.json['已發送檔案清單'] || folder.json['已發送檔案'] || folder.json['今日檔案列表']).trim() : '';
  const targetFileNamesArray = sentFilesString ? sentFilesString.split(',').map(s => s.trim()) : [];

  if (fId && fName) {
    const prefix = String(fName).trim().substring(0, 3);

    let companyName = String(fName).trim();
    const parts = companyName.split('-');
    if (parts.length >= 3) {
      companyName = parts[1].trim();
    } else if (parts.length === 2) {
      companyName = parts[1].trim();
    }

    folderMap[fId] = {
      prefix: prefix,
      companyName: companyName,
      targetFileNames: targetFileNamesArray
    };
  }
}

const userGroupedMatches = {};

for (const fileItem of allFiles) {
  if (!fileItem || !fileItem.json || !fileItem.json.name || !fileItem.json.id) {
    continue;
  }

  const fileName = fileItem.json.name.trim();
  const fileId = fileItem.json.id;

  const forceDownloadUrl = `https://drive.google.com/uc?export=download&id=${fileId}&openExternalBrowser=1`;
  const parents = fileItem.json.parents;
  const parentFolderId = (Array.isArray(parents) && parents.length > 0) ? parents[0] : null;

  const folderData = parentFolderId ? folderMap[parentFolderId] : null;
  if (!folderData) {
    continue;
  }

  // 白名單比對：必須存在於 F 欄紀錄
  if (folderData.targetFileNames.length === 0 || !folderData.targetFileNames.includes(fileName)) {
    continue;
  }

  const folderPrefix = folderData.prefix;
  const companyName = folderData.companyName;

  for (const row of customerMap) {
    const userId = row.json['B:userId'];
    if (!userId) continue;

    const clientCodes = [];
    const colNames = ['編號1', '編號2', '編號3', '編號4', '編號5', '編號6', '編號7', '編號8', '編號9', '編號10'];

    for (const col of colNames) {
      const val = row.json[col];
      if (val !== undefined && val !== null && val !== '') {
        clientCodes.push(String(val).trim());
      }
    }

    const isMatch = clientCodes.some(code => code !== '' && folderPrefix === code);

    if (isMatch) {
      if (!userGroupedMatches[userId]) {
        userGroupedMatches[userId] = { lineUserId: userId, companies: {} };
      }

      if (!userGroupedMatches[userId].companies[parentFolderId]) {
        userGroupedMatches[userId].companies[parentFolderId] = { companyName: companyName, files: [] };
      }

      const targetCompany = userGroupedMatches[userId].companies[parentFolderId];
      const isFileAlreadyAdded = targetCompany.files.some(f => f.fileId === fileId);

      if (!isFileAlreadyAdded) {
        targetCompany.files.push({
          fileId: fileId,
          fileName: fileName,
          fileUrl: forceDownloadUrl
        });
      }
    }
  }
}

const outputData = Object.values(userGroupedMatches).map(user => ({
  json: {
    lineUserId: user.lineUserId,
    companies: Object.values(user.companies)
  }
}));

return outputData.length > 0 ? outputData : [];

// ==========================================
// 1. 取得前三步的資料
// ==========================================
const files = $('1. 讀取 Drive 發票 PDF').all();
const clients = $('2. 讀取最新客戶資料').all();
const lineSheet = $('3. 讀取客戶 LINE ID Sheet').all();

// 建立統編對應客戶資料的 Map (以「統一編號」為 Key)
const taxToClientMap = {};
clients.forEach(item => {
  const row = item.json;
  const taxId = String(row['統一編號'] || '').trim();
  if (taxId) {
    taxToClientMap[taxId] = row;
  }
});

// 建立客戶編號對應 LINE ID 的 Map (除了 lineId 外，一併存入 displayName)
const clientNoToLineIdsMap = {};
lineSheet.forEach(item => {
  const row = item.json;

  // 檢查 D 欄位（message）是否包含「帳單」
  const msgType = String(row['D:message'] || row['message'] || '').trim();
  if (!msgType.includes('帳單')) return;

  const lineId = String(row['B:userId'] || '').trim();
  const displayName = String(row['C:displayName'] || '').trim(); // 取得顯示名稱
  if (!lineId) return;

  for (let i = 1; i <= 10; i++) {
    const clientNoKey = `編號${i}`;
    const clientNo = String(row[clientNoKey] || '').trim();
    if (clientNo) {
      if (!clientNoToLineIdsMap[clientNo]) {
        clientNoToLineIdsMap[clientNo] = [];
      }
      // 檢查是否已加入過該 lineId
      if (!clientNoToLineIdsMap[clientNo].some(user => user.lineId === lineId)) {
        clientNoToLineIdsMap[clientNo].push({
          lineId: lineId,
          displayName: displayName
        });
      }
    }
  }
});

// ==========================================
// 2. 解析檔名並進行三方比對 (一對多推播)
// ==========================================
const matchedInvoices = [];
const debugLogs = [];

files.forEach(fileItem => {
  const fileName = fileItem.json.name || '';
  const webViewLink = fileItem.json.webViewLink || '';

  // 抓取括號內的 8 位數字統編
  const taxMatch = fileName.match(/\((\d{8})/);
  const taxId = taxMatch ? taxMatch[1] : '';

  // 抓取發票號碼
  const invMatch = fileName.match(/([A-Z]{2}\d{8})/i);
  const invNumber = invMatch ? invMatch[1].toUpperCase() : '未知號碼';

  // 查客戶資料表
  const clientInfo = taxToClientMap[taxId] || {};
  const companyName = clientInfo['客戶名稱'] || '貴公司';
  const clientNo = String(clientInfo['編號'] || '').trim();

  // 查對應的所有 LINE User 物件陣列
  const targetUsers = clientNoToLineIdsMap[clientNo] || [];

  if (targetUsers.length > 0) {
    targetUsers.forEach(user => {
      matchedInvoices.push({
        lineId: user.lineId,
        displayName: user.displayName,
        companyName: companyName,
        invNumber: invNumber,
        pdfUrl: webViewLink
      });
    });
  } else {
    debugLogs.push({
      fileName,
      extractedTaxId: taxId,
      extractedInvNumber: invNumber,
      foundClientNo: clientNo,
      reason: !taxId ? '檔名括號內未抓到 8 位統編' : (!clientNo ? '客戶資料表找不到此統編' : `客戶編號 [${clientNo}] 在 LINE ID Sheet 的編號1~10 找不到對應`)
    });
  }
});

// ==========================================
// 3. 依 LINE ID 歸戶與排序 (Group & Sort By InvNumber)
// ==========================================
const groupedByLine = {};

matchedInvoices.forEach(inv => {
  if (!groupedByLine[inv.lineId]) {
    groupedByLine[inv.lineId] = {
      lineId: inv.lineId,
      displayName: inv.displayName,
      invoices: []
    };
  }
  groupedByLine[inv.lineId].invoices.push(inv);
});

// 對每個 LINE ID 內的發票依發票號碼升冪排序
Object.values(groupedByLine).forEach(group => {
  group.invoices.sort((a, b) => a.invNumber.localeCompare(b.invNumber));
});

// ==========================================
// 4. 組裝 Flex Message (同一 ID 的多筆發票合併至單一 Bubble)
// ==========================================
const finalOutput = Object.values(groupedByLine).map(group => {

  // 1. 建立頂部標頭與提示文字
  const bubbleBodyContents = [
    {
      "type": "text",
      "text": "📄 電子發票開立通知",
      "weight": "bold",
      "color": "#1DB446",
      "size": "md"
    },
    {
      "type": "text",
      "text": "您好！",
      "weight": "bold",
      "size": "md",
      "margin": "md"
    },
    {
      "type": "text",
      "text": "貴公司電子發票證明聯已開立完成。",
      "size": "sm",
      "color": "#555555",
      "margin": "xs"
    },
    {
      "type": "text",
      "text": "💡 提示：本發票會在9月自動扣抵，如有內帳需求請自行列印。",
      "size": "md",
      "color": "#1570EF",
      "wrap": true,
      "margin": "md"
    },
    {
      "type": "separator",
      "margin": "lg"
    }
  ];

  // 2. 依序動態加入排序後的公司名稱與下載按鈕
  group.invoices.forEach((inv, index) => {
    if (index > 0) {
      bubbleBodyContents.push({
        "type": "separator",
        "margin": "lg"
      });
    }

    bubbleBodyContents.push(
      {
        "type": "text",
        "text": inv.companyName,
        "weight": "bold",
        "size": "lg",
        "color": "#333333",
        "margin": "lg",
        "wrap": true
      },
      {
        "type": "button",
        "action": {
          "type": "uri",
          "label": `下載發票 (${inv.invNumber})`,
          "uri": inv.pdfUrl
        },
        "style": "primary",
        "color": "#1DB446",
        "height": "sm",
        "margin": "md"
      }
    );
  });

  // 3. 打包成單一 Flex Message Bubble
  const flexPayload = {
    "type": "flex",
    "altText": "您有新的電子發票通知",
    "contents": {
      "type": "bubble",
      "size": "mega",
      "body": {
        "type": "box",
        "layout": "vertical",
        "contents": bubbleBodyContents
      }
    }
  };

  return {
    json: {
      to: group.lineId,
      displayName: group.displayName,
      flexPayload: flexPayload
    }
  };
});

// ==========================================
// 5. 安全結束：沒有匹配成功時回傳空陣列
// ==========================================
if (finalOutput.length === 0) {
  // 印在 n8n 的 Node 執行 Log 中供排錯使用，但不輸出任何資料給下一個節點
  console.log("沒有符合條件的發票資料，debugLogs：", debugLogs.slice(0, 10));
  return []; // 直接回傳 []，下一個 LINE 發送節點將不會被觸發，流程成功結束
}

return finalOutput;

// 取得 LINE Webhook 傳入的文字訊息
const rawText = $input.first().json.body?.events?.[0]?.message?.text || "";

// 正則表達式說明：
// (U[a-fA-F0-9]{32}) : 捕獲組 1 -> 33 碼 LINE User ID
// \s+                : 至少 1 個空白或換行符號
// (\S+)              : 捕獲組 2 -> 後續接的任意代碼（不含空白，包含 /、數字、中文等）
const regex = /(U[a-fA-F0-9]{32})\s+(\S+)/;
const match = rawText.match(regex);

let userId = null;
let code = null;
let success = false;

if (match) {
  success = true;
  userId = match[1];
  code = match[2]; // 自動保留原始的代碼內容 (有 / 就留 /，沒有就直接抓文字/數字)
}

return [
  {
    json: {
      success: success,
      rawText: rawText,
      userId: userId,
      code: code
    }
  }
];

// ==========================================
// 1. 取得 Trigger 傳入的所有檔案項目
// ==========================================
const items = $input.all();

// ==========================================
// 2. 關鍵安全性過濾（排除非 PDF 與暫存檔）
// ==========================================
const validItems = items.filter(item => {
    const fileName = item.json.name;

    // 如果沒有檔名，直接過濾掉
    if (!fileName) return false;

    const lowerName = fileName.toLowerCase();

    // 必須是 .pdf 結尾，且不能是 Google 生成時的暫時檔名 'export.pdf'
    return lowerName.endsWith('.pdf') && lowerName !== 'export.pdf';
});

// ==========================================
// 3. 處理檔名轉換與組裝輸出資料
// ==========================================
// 註：這裡不再用 slice() 限制批次筆數。
// Zeabur 轉檔服務已經用 semaphore 做同時併發數限制，
// n8n 這邊一次抓到幾筆就往下送幾筆，多餘的請求會在伺服器端自動排隊，
// 不會再有檔案因為被砍掉而永久遺失。
return validItems.map(item => {
    // 提取檔名與檔案 ID
    const fileName = item.json.name;
    const fileId = item.json.id;

    // 剔除原本的副檔名 (例如：report.pdf -> report)
    const cleanName = fileName.replace(/\.[^/.]+$/, "");

    // 組裝輸出的 JPG 檔名與 Telegram 通知訊息
    const outputJpgName = `${cleanName}.jpg`;
    const tgMessage = `📄 ${fileName} 已成功送出轉檔`;

    // 回傳精簡資料給後續節點（Download -> HTTP Request -> Upload -> Move）使用
    return {
        json: {
            originalId: String(fileId),
            originalName: String(fileName),
            jpgName: String(outputJpgName),
            tgText: String(tgMessage)
        }
    };
});

// 1. 跨節點直接抓取「Code in JavaScript1」這個節點輸出的所有項目資料
const sourceItems = $('Code in JavaScript1').all();

// 2. 提取出所有項目的 tgText 欄位，並用換行符號連接起來
const fileList = sourceItems.map((item, index) => {
    // 如果找不到 tgText，就顯示未知名稱
    const text = item.json.tgText || "未取得文字資訊";
    return `${index + 1}. ${text}`;
}).join('\n');

// 3. 計算總共有多少個檔案
const totalCount = sourceItems.length;

// 4. 組裝成最終要發送給 Telegram 的單一訊息
const finalMessage = `
${fileList}

統計：共成功轉換 ${totalCount} 個檔案。
`.trim();

// 5. 只回傳一個項目給 Telegram 與後續 Webhook 節點
return [
  {
    json: {
      combinedMessage: finalMessage,
      fileCount: totalCount
    }
  }
];

// ==========================================
// 1. 核心通用配置與函式
// ==========================================
const pageSize = 4; // 每頁最多顯示的公司數量
const TIME_TOLERANCE_MS = 120000; // 容許時間差：2 分鐘 (120,000 毫秒)

// 千分位格式化函式
const formatPrice = (val) => {
  if (val === undefined || val === null || val === "" || isNaN(parseFloat(val))) return "--";
  return parseFloat(val).toLocaleString('en-US');
};

// 解析修改狀態時間點
function parseModifyStatusToMs(statusStr) {
  const str = String(statusStr || "").trim();
  let match = str.match(/(\d{1,2})\/(\d{1,2})\s+(\d{1,2}):(\d{1,2})修改/);
  if (match) {
    const month = parseInt(match[1], 10) - 1;
    const day = parseInt(match[2], 10);
    const hour = parseInt(match[3], 10);
    const minute = parseInt(match[4], 10);
    const currentYear = new Date().getFullYear();
    return new Date(currentYear, month, day, hour, minute, 0, 0).getTime();
  }
  match = str.match(/修改(?:\d+_)?(\d{2})(\d{2})-(\d{2})(\d{2})/);
  if (!match) return 0;
  const month = parseInt(match[1], 10) - 1;
  const day = parseInt(match[2], 10);
  const hour = parseInt(match[3], 10);
  const minute = parseInt(match[4], 10);
  const currentYear = new Date().getFullYear();
  return new Date(currentYear, month, day, hour, minute, 0, 0).getTime();
}

// 生成單一用戶的 Flex Carousel
function generateFlexCarousel(clients, amounts, statuses, links, changeTimes, bankAccountRaw, displayName = "") {
  let bankAccount = bankAccountRaw || "暫無帳號資訊";
  bankAccount = bankAccount.replace(/(北中壢分行)[\s\u3000]*/g, "$1\n");

  let anyNotIssued = false;
  let anyModifying = false; // 紀錄是否有任何帳單修改中
  let calculatedTotalAmount = 0;
  let latestTimeMs = 0;
  const clientTimesMs = [];
  const downloadableClients = [];

  for (let j = 0; j < clients.length; j++) {
    const checkAmt = amounts[j];
    const checkLink = String(links[j] || "").trim();
    const rawStatus = String(statuses[j] || "").trim();
    const ct = String(changeTimes[j] ?? "0").trim();
    const isModifying = ct !== "0" && ct !== "";
    const isNotIssued = checkLink === "尚未出帳" || String(checkAmt).includes("#N/A");

    if (isNotIssued) anyNotIssued = true;
    if (isModifying) anyModifying = true;

    if (!isNotIssued && !isModifying) {
      downloadableClients.push(clients[j]);
      if (!isNaN(parseFloat(checkAmt))) {
        calculatedTotalAmount += parseFloat(checkAmt);
      }
    }

    const timeMs = parseModifyStatusToMs(rawStatus);
    clientTimesMs.push(timeMs);
    if (timeMs > latestTimeMs) latestTimeMs = timeMs;
  }

  const isLatestModified = [];
  for (let j = 0; j < clients.length; j++) {
    const rawStatus = String(statuses[j] || "").trim();
    const hasModifyMark = rawStatus.includes("修改");
    isLatestModified.push(clients.length > 1 && hasModifyMark);
