      "layout": "vertical",
      "paddingBottom": "none",
      "contents": [
        { "type": "text", "text": "🔔 帳單通知", "weight": "bold", "size": "lg", "color": "#111111" }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "paddingTop": "md",
      "spacing": "md",
      "contents": [
        { 
          "type": "text", 
          "text": "請盡速核對帳單，如有錯誤請儘速告知修正：", 
          "wrap": true, 
          "size": "md", 
