              "type": "box",
              "layout": "vertical",
              "flex": 1,
              "contents": [
                { "type": "text", "text": "下載帳單", "weight": "bold", "size": "lg", "color": "#111111" },
                { "type": "text", "text": "點下方按鈕下載帳單明細", "size": "md", "color": "#666666", "margin": "xs" }
