          "layout": "horizontal",
          "spacing": "md",
          "margin": "md",
          "contents": [
            {
              "type": "text",
              "text": "❸",
              "size": "xl",
              "color": "#1DB446",
              "weight": "bold",
              "flex": 0,
              "gravity": "center"
            },
            {
              "type": "box",
              "layout": "vertical",
              "flex": 1,
              "contents": [
