      groupedContacts[userId].allCodes.add(String(codeVal).trim());
    }
  }

  if (contact["編號"] && String(contact["編號"]).trim() !== "") {
    groupedContacts[userId].allCodes.add(String(contact["編號"]).trim());
  }
});

// 4. 比對出真正需要更新與發送通知的資料 (每 5 家公司切分為一張卡片，組成 Carousel)
Object.values(groupedContacts).forEach(userGroup => {
  const userId = userGroup.userId;
  const displayName = userGroup.displayName;
  const matchedBills = [];

  userGroup.allCodes.forEach(cleanCode => {
    const matchedBill = billMap[cleanCode];
    if (matchedBill) {
      matchedBills.push(matchedBill);
      updateCodesSet.add(cleanCode);

      if (!personToCompanies[displayName]) {
        personToCompanies[displayName] = new Set();
      }
      personToCompanies[displayName].add(matchedBill["客戶名稱"].trim());
    }
  });

  if (matchedBills.length === 0) return;

  // 計算全部帳單總金額
  const grandTotalAmount = matchedBills.reduce((sum, b) => sum + (parseFloat(b["已入金額"]) || 0), 0);

  // 設定每張卡片最多放 5 家客戶
  const CHUNK_SIZE = 5;
  const totalPages = Math.ceil(matchedBills.length / CHUNK_SIZE);
  const bubbles = [];

  for (let i = 0; i < matchedBills.length; i += CHUNK_SIZE) {
    const chunk = matchedBills.slice(i, i + CHUNK_SIZE);
    const currentPage = Math.floor(i / CHUNK_SIZE) + 1;

    // 標題設定 (配合圖片風格加上 Icon 與深藍色)
    const headerTitle = totalPages > 1 
      ? `款項入帳完成通知 (${currentPage}/${totalPages})` 
      : `款項入帳完成通知`;

    const bodyContents = [
      {
        "type": "box",
        "layout": "horizontal",
        "margin": "none",
        "contents": [
          {
            "type": "text",
            "text": "✅",
            "size": "md",
            "flex": 0,
            "margin": "none"
          },
          {
            "type": "text",
            "text": headerTitle,
            "weight": "bold",
            "size": "md",
            "color": "#1E3A8A",
            "margin": "sm",
            "flex": 1,
            "adjustMode": "shrink-to-fit"
          }
        ]
      },
      {
        "type": "separator",
        "margin": "md",
        "color": "#E2E8F0"
      }
    ];

    let chunkTotalAmount = 0;

    chunk.forEach((bill, idx) => {
      const companyName = String(bill["客戶名稱"] || "").trim();
      const amtVal = parseFloat(bill["已入金額"]) || 0;
      chunkTotalAmount += amtVal;

      // 左右 7:3 排版，顏色與字體比照帳單總覽
      bodyContents.push({
        "type": "box",
        "layout": "horizontal",
        "margin": (idx === 0) ? "lg" : "md",
        "paddingStart": "md",
        "paddingEnd": "md",
        "contents": [
          {
            "type": "text",
            "text": companyName,
            "weight": "bold",
            "size": "sm",
            "color": "#0F172A",          // 深色字體
            "flex": 7,                   // 左側 7 份寬度
            "wrap": true,                // 允許換行
            "maxLines": 2,               // 最多跨到第二排
            "adjustMode": "shrink-to-fit"
          },
          {
            "type": "text",
            "text": `${formatPrice(amtVal)}`, // 只有金額數字
            "weight": "bold",
            "size": "sm",
            "color": "#1E3A8A",          // 藍色字體 (比照圖片中的金額樣式)
            "flex": 3,                   // 右側 3 份寬度
            "align": "end",              // 靠右對齊
            "gravity": "center"          // 若公司名稱換行，金額垂直置中
          }
        ]
      });
    });

    // 合計區塊 (模仿圖片右側的總計樣式：淺灰底、紅色大字)
    if (totalPages > 1 || chunk.length > 1) {
      const totalBoxContents = [];

      if (currentPage === totalPages) {
        totalBoxContents.push({
          "type": "text",
          "text": "合計總金額",
          "size": "xs",
          "color": "#64748B",
          "align": "end"
        });
        totalBoxContents.push({
          "type": "text",
          "text": `NT$ ${formatPrice(grandTotalAmount)}`,
          "size": "xl",
          "color": "#EF4444",
          "weight": "bold",
          "align": "end",
          "margin": "xs"
        });
      } else {
        totalBoxContents.push({
          "type": "text",
          "text": "本頁小計",
          "size": "xs",
          "color": "#64748B",
          "align": "end"
        });
        totalBoxContents.push({
          "type": "text",
          "text": `NT$ ${formatPrice(chunkTotalAmount)}`,
          "size": "xl",
          "color": "#1E3A8A",
          "weight": "bold",
          "align": "end",
          "margin": "xs"
        });
      }

      bodyContents.push({
        "type": "box",
        "layout": "vertical",
        "margin": "xl",
        "paddingAll": "md",
        "backgroundColor": "#F8FAFC",
        "cornerRadius": "md",
        "contents": totalBoxContents
      });
    }

    bubbles.push({
      "type": "bubble",
      "size": "kilo",
      "body": {
        "type": "box",
        "layout": "vertical",
        "contents": bodyContents
      },
      "footer": {
        "type": "box",
        "layout": "vertical",
        "contents": [
          {
            "type": "text",
            "text": "感謝您的支持與配合",
            "size": "sm",
            "color": "#64748B",
            "align": "center",
            "wrap": true
          }
        ]
      }
    });
  }

  // 判斷：單頁傳 Bubble；多頁包裝為 Carousel
  const flexPayload = totalPages > 1
    ? { "type": "carousel", "contents": bubbles }
    : bubbles[0];

  lineTasks.push({
    userId: userId,
    flexJsonString: JSON.stringify(flexPayload)
  });
});

// 5. 彙整 Telegram 報告
const tgKeys = Object.keys(personToCompanies).filter(k => personToCompanies[k].size > 0);
let tgText = "<b>💵 已確認收款摘要</b>\n";
tgText += `<code>共計發送 ${tgKeys.length} 個帳號</code>\n\n`;

tgKeys.forEach(name => {
  tgText += `<b>🟢 ${name} </b>\n`;
  Array.from(personToCompanies[name]).forEach(company => {
    tgText += ` • ${company}\n`;
  });
  tgText += "\n";
});

// 6. 彙整待回寫 401 表的「已繳」更新清單
const updateList = Array.from(updateCodesSet).map(code => ({
  "編號": code,
  "狀態": "已繳款"
}));

if (updateList.length === 0) return [];

return [{
  json: {
    lineTasks: lineTasks,
    tgText: tgText,
    updateList: updateList
  }
}];

